typescript.originalService:
class CoCoMESystem_AutoGenerated {
  /*SystemVariable Start*/
  CurrentCashDesk: CashDesk;
  CurrentStore: Store;
  /*SystemVariable End*/

  /*find order product with provided order id,
   *if the order product exists,
   *the status should be received,
   *and the contained entries' items' stock number should plus the quentity*/
  receiveOrderedProduct(orderID: number): boolean {
    /*Definition Start*/
    let op: OrderProduct = l({
      logic: () =>
        getRepository(OrderProduct).find(
          (o: any) =>
            l({
              logic: () => o.Id === orderID,
              description: "o.Id=orderID",
            }).build().pass,
        ),
      description: "OrderProduct.allInstance()->any(o|o.Id=orderID)",
    }).build().pass;
    let oe: OrderEntry[] = l({
      logic: () => op.ContainedEntries,
      description: "op.ContainedEntries",
    }).build().pass;
    let items: Item[] = l({
      logic: () => oe.Item,
      description: "oe.Item",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => getRepository(OrderProduct).includes(op),
        description: "OrderProduct.allInstance()->includes(op)",
      })
        .and({
          logic: () => op.OrderStatus === OrderProduct.RECEIVED,
          description: "op.OrderStatus=OrderProduct::RECEIVED",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    return l({
      execute: () => getRepository(OrderProduct).push(op),
      description: "OrderProduct.allInstance()->includes(op)",
    })
      .and({
        execute: () => (op.OrderStatus = OrderProduct.RECEIVED),
        description: "op.OrderStatus=OrderProduct::RECEIVED",
      })
      .and({
        execute: () =>
          oe.forEach(
            (e: any) =>
              l({
                execute: () =>
                  (e.Item.StockNumber = e.Item.StockNumber + e.Quantity),
                description: "e.Item.StockNumber=e.Item.StockNumber+e.Quantity",
              }).build().value,
          ),
        description:
          "oe->forAll(e|e.Item.StockNumber=e.Item.StockNumber+e.Quantity)",
      })
      .and({
        execute: () => true,
        description: "result=true",
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { CoCoMESystem_AutoGenerated };

