        .and({
          logic: () => orderProduct.OrderStatus === OrderStatus.RECEIVED,
          description: "orderProduct.OrderStatus=OrderStatus::RECEIVED",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    return l({
      execute: () => (orderProduct.OrderStatus = "RECEIVED"),
      description: 'orderProduct.OrderStatus="RECEIVED"',
    })
      .and({
        execute: () =>
          items.forEach(
            (item: any) =>
              l({
                execute: () =>
                  orderEntries.some(
                    (entry: any) =>
                      l({
                        logic: () => entry.Item === item,
