class CoCoMESystem_AutoGenerated {
  /*SystemVariable Start*/
  CurrentCashDesk: CashDesk;
  CurrentStore: Store;
  /*SystemVariable End*/

  /*find order product with provided order id,
   *if the order product exists,
   *the status should be received,
   *and the contained entries' items' stock number should plus the quentity*/
  receiveOrderedProduct(orderID: number): boolean {
    /*Definition Start*/
    let orderProduct: OrderProduct = l({
      logic: () =>
        getRepository(OrderProduct).find(
          (o: any) =>
            l({
              logic: () => o.Id === orderID,
              description: "o.Id=orderID",
            }).build().pass,
        ),
      description: "OrderProduct.allInstance()->any(o|o.Id=orderID)",
    }).build().pass;
    let orderEntries: OrderEntry[] = l({
      logic: () => orderProduct.ContainedEntries,
      description: "orderProduct.ContainedEntries",
    }).build().pass;
    let items: Item[] = l({
      logic: () =>
        orderEntries.map(
          (e: any) =>
            l({
              logic: () => e.Item,
              description: "e.Item",
            }).build().pass,
        ),
      description: "orderEntries->collect(e|e.Item)",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => getRepository(OrderProduct).includes(orderProduct),
        description: "OrderProduct.allInstance()->includes(orderProduct)",
      })
        .and({
          logic: () => orderProduct.OrderStatus === OrderStatus.RECEIVED,
          description: "orderProduct.OrderStatus=OrderStatus::RECEIVED",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let orderProduct: any;
    return l({
      execute: () => (orderProduct = new OrderProduct()),
      description: "orderProduct.oclIsNew()",
    })
      .and({
        execute: () =>
          items.forEach(
            (item: any) =>
              l({
                execute: () =>
                  orderEntries.some(
                    (entry: any) =>
                      l({
                        logic: () => entry.Item === item,
                        description: "entry.Item=item",
                      })
                        .and({
                          logic: () =>
                            item.StockNumber ===
                            item.StockNumber + entry.Quantity,
                          description:
                            "item.StockNumber=item.StockNumber+entry.Quantity",
                        })
                        .build().pass,
                  ),
                description:
                  "orderEntries->exists(entry|entry.Item=itemanditem.StockNumber=item.StockNumber+entry.Quantity)",
              }).build().value,
          ),
        description:
          "items->forAll(item|orderEntries->exists(entry|entry.Item=itemanditem.StockNumber=item.StockNumber+entry.Quantity))",
      })
      .and({
        execute: () => true,
        description: "result=true",
      })
      .build().value;
    /*Postcondition End*/
  }
}

